import{_ as a,o,c as t,a6 as s}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"Cookie","description":"Set-Cookie 的七个属性、Cookie 请求语法、SameSite 与 __Host- 前缀规则。","frontmatter":{"title":"Cookie","description":"Set-Cookie 的七个属性、Cookie 请求语法、SameSite 与 __Host- 前缀规则。","source":"https://daiw.org/manual/http11/cookies"},"headers":[],"relativePath":"manual/computer-programming/http11/cookies.md","filePath":"manual/computer-programming/http11/cookies.md"}'),n={name:"manual/computer-programming/http11/cookies.md"};function i(r,e,d,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="cookie" tabindex="-1">Cookie <a class="header-anchor" href="#cookie" aria-label="Permalink to &quot;Cookie&quot;">​</a></h1><p>规范基准 <strong>RFC 6265</strong>（及其修订草案 6265bis）。Cookie <strong>不属于</strong> HTTP 核心语义（RFC 9110），是独立的状态管理层。</p><h2 id="set-cookie" tabindex="-1">Set-Cookie <a class="header-anchor" href="#set-cookie" aria-label="Permalink to &quot;Set-Cookie&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set-cookie        = cookie-pair *( &quot;;&quot; SP cookie-av )</span></span>
<span class="line"><span>cookie-pair       = cookie-name &quot;=&quot; cookie-value</span></span>
<span class="line"><span>cookie-name       = token</span></span>
<span class="line"><span>cookie-value      = *cookie-octet / ( DQUOTE *cookie-octet DQUOTE )</span></span>
<span class="line"><span>cookie-octet      = %x21 / %x23-2B / %x2D-3A / %x3C-5B / %x5D-7E</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Set-Cookie: sid=abc123; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=3600</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>硬性规则：</p><ul><li><strong>每个 Cookie 一个 <code>Set-Cookie</code> 字段行</strong>。该字段 <strong>MUST NOT</strong> 被合并成逗号分隔的单行——其 <code>Expires</code> 值内部含逗号，合并即破坏解析。这是<a href="/Front2Full/manual/computer-programming/http11/field-syntax">字段合并规则</a>的头号例外。</li><li><code>cookie-value</code> <strong>不得</strong>含空白、逗号、分号、反斜杠。需要这些字符时自行做百分号或 Base64 编码——规范<strong>不定义</strong>任何编码。</li><li>属性名<strong>大小写不敏感</strong>；未知属性 <strong>MUST</strong> 被忽略。</li><li>属性顺序无意义，但同名属性<strong>以最后一个为准</strong>。</li></ul><h2 id="七个属性" tabindex="-1">七个属性 <a class="header-anchor" href="#七个属性" aria-label="Permalink to &quot;七个属性&quot;">​</a></h2><h3 id="expires" tabindex="-1">Expires <a class="header-anchor" href="#expires" aria-label="Permalink to &quot;Expires&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Expires = &lt;sane-cookie-date&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>绝对过期时刻（IMF-fixdate）。无 <code>Expires</code> 且无 <code>Max-Age</code> → <strong>会话 Cookie</strong>，浏览器关闭即删。</p><p>设为<strong>过去</strong>的时间是删除 Cookie 的标准做法——且删除时的 <code>Path</code>/<code>Domain</code> <strong>必须与设置时完全一致</strong>，否则删不掉（高频 bug）。</p><h3 id="max-age" tabindex="-1">Max-Age <a class="header-anchor" href="#max-age" aria-label="Permalink to &quot;Max-Age&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Max-Age = [ &quot;-&quot; ] 1*DIGIT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>相对秒数。<strong>优先级高于 <code>Expires</code></strong>——两者同时存在时 <code>Max-Age</code> 胜出（不受客户端时钟偏差影响）。</p><p><code>Max-Age=0</code> 或负值 → 立即删除。</p><h3 id="domain" tabindex="-1">Domain <a class="header-anchor" href="#domain" aria-label="Permalink to &quot;Domain&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Set-Cookie: a=1; Domain=example.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>反直觉规则：</p><ul><li>指定 <code>Domain</code> → Cookie 对该域<strong>及其所有子域</strong>可见（<code>example.com</code> + <code>www.example.com</code> + <code>api.example.com</code>）。</li><li><strong>不指定</strong> <code>Domain</code> → 仅对<strong>当前精确主机</strong>可见，<strong>不含</strong>子域。<strong>不指定反而更严格</strong>。</li><li>前导点（<code>Domain=.example.com</code>）在 6265 中<strong>被忽略</strong>，等价于无点形式。</li><li><strong>不得</strong>设为公共后缀（<code>.com</code>、<code>.co.uk</code>）或上级无关域——浏览器按 Public Suffix List 拒绝。</li></ul><h3 id="path" tabindex="-1">Path <a class="header-anchor" href="#path" aria-label="Permalink to &quot;Path&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Set-Cookie: a=1; Path=/admin</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>匹配规则：请求路径等于该值，或以该值加 <code>/</code> 为前缀。<code>Path=/admin</code> 匹配 <code>/admin</code>、<code>/admin/x</code>，<strong>不匹配</strong> <code>/administrator</code>。</li><li>缺省值由请求 URI <strong>推导</strong>：取最后一个 <code>/</code> 之前的部分（<code>/a/b/c</code> → <code>/a/b</code>），而非 <code>/</code>。</li><li><strong><code>Path</code> 不是安全边界</strong>——同源不同路径的脚本可通过 iframe 等方式互访。不要用它做隔离。</li></ul><h3 id="secure" tabindex="-1">Secure <a class="header-anchor" href="#secure" aria-label="Permalink to &quot;Secure&quot;">​</a></h3><p>仅通过<strong>安全传输</strong>（HTTPS）发送。</p><p>注意：<code>Secure</code> 只防「明文发出」，<strong>不防</strong>「被明文写入」——非安全来源的脚本仍可能覆盖同名 Cookie（除非用 <code>__Secure-</code> 前缀）。</p><h3 id="httponly" tabindex="-1">HttpOnly <a class="header-anchor" href="#httponly" aria-label="Permalink to &quot;HttpOnly&quot;">​</a></h3><p>禁止 JavaScript（<code>document.cookie</code>）访问。是防 XSS 窃取会话的基本手段，<strong>会话 Cookie 必须开启</strong>。</p><h3 id="samesite" tabindex="-1">SameSite <a class="header-anchor" href="#samesite" aria-label="Permalink to &quot;SameSite&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SameSite = &quot;Strict&quot; / &quot;Lax&quot; / &quot;None&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>控制跨站请求是否携带：</p><table tabindex="0"><thead><tr><th>值</th><th>行为</th></tr></thead><tbody><tr><td><code>Strict</code></td><td>任何跨站请求都<strong>不</strong>携带，含从外站点击链接跳入</td></tr><tr><td><code>Lax</code></td><td>跨站的<strong>顶层导航 GET</strong> 携带；跨站 <code>POST</code>、iframe、img、XHR <strong>不</strong>携带</td></tr><tr><td><code>None</code></td><td>始终携带，<strong>MUST</strong> 同时带 <code>Secure</code>，否则浏览器拒绝（跨站嵌入场景可配 <code>Partitioned</code> 启用 CHIPS 分区存储）</td></tr></tbody></table><p>现代浏览器在<strong>缺省时按 <code>Lax</code></strong> 处理（6265bis 方向），但该默认不是规范强制，<strong>应显式声明</strong>。</p><p><code>SameSite=Lax</code> 已可挡住大部分 CSRF，但不能替代 CSRF token——它不防同站攻击，且旧客户端不支持。</p><h2 id="cookie-请求字段" tabindex="-1">Cookie（请求字段） <a class="header-anchor" href="#cookie-请求字段" aria-label="Permalink to &quot;Cookie（请求字段）&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cookie-header = &quot;Cookie:&quot; OWS cookie-string OWS</span></span>
<span class="line"><span>cookie-string = cookie-pair *( &quot;;&quot; SP cookie-pair )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cookie: sid=abc123; theme=dark; lang=zh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>关键差异：</p><ul><li><strong>只发名值对，不发任何属性</strong>——服务端<strong>无法</strong>从请求得知某 Cookie 的 <code>Domain</code>、<code>Path</code>、<code>Secure</code> 等。</li><li>分隔符是 <strong><code>;</code></strong> （分号加空格），不是逗号。</li><li>多个同名 Cookie（不同 <code>Domain</code>/<code>Path</code>）<strong>可以</strong>同时出现，且<strong>顺序不保证</strong>、无法区分来源——这是「Cookie 覆盖/投毒」类攻击的基础。</li><li>所有 Cookie 在<strong>同一个</strong> <code>Cookie</code> 字段中发送（不像 <code>Set-Cookie</code> 每个一行）。</li><li>无 Cookie 时<strong>不发</strong>该字段（不发空字段）。</li></ul><h2 id="安全前缀" tabindex="-1">安全前缀 <a class="header-anchor" href="#安全前缀" aria-label="Permalink to &quot;安全前缀&quot;">​</a></h2><p>浏览器对特定名字前缀强制附加约束：</p><table tabindex="0"><thead><tr><th>前缀</th><th>强制要求</th></tr></thead><tbody><tr><td><code>__Secure-</code></td><td>必须带 <code>Secure</code>，且由安全来源设置</td></tr><tr><td><code>__Host-</code></td><td>必须带 <code>Secure</code>、<code>Path=/</code>、<strong>且不得带 <code>Domain</code></strong>，由安全来源设置</td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Set-Cookie: __Host-sid=abc; Path=/; Secure; HttpOnly; SameSite=Lax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>__Host-</code> 是<strong>最强</strong>形式：它保证该 Cookie 只属于当前精确主机，子域无法写入或覆盖——能挡住子域接管类攻击。会话 Cookie 应优先使用。</p><h2 id="容量限制" tabindex="-1">容量限制 <a class="header-anchor" href="#容量限制" aria-label="Permalink to &quot;容量限制&quot;">​</a></h2><p>规范建议的下限（浏览器实际值接近）：</p><ul><li>每个 Cookie ≥ 4096 字节（名 + 值 + 属性总长）。</li><li>每个域 ≥ 50 个。</li><li>总数 ≥ 3000 个。</li></ul><p>超限时浏览器按最近最少使用淘汰，<strong>静默丢弃</strong>——不会有任何错误提示。Cookie 过大还会显著拖慢每个请求（每请求都全量携带）。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文与控制字段</a>。</p>`,49)])])}const g=a(n,[["render",i]]);export{h as __pageData,g as default};
